def make_node(path_name, ch, cid, i):
 # children can be a str of leaves, or nested tuples
 if isinstance(ch,str):
  parts=[x.strip() for x in ch.split('|') if x.strip()]
  return {'id':f'{cid}-t{i}','title':path_name,'children':[{'id':f'{cid}-t{i}-{j}','title':s,'children':[]} for j,s in enumerate(parts,1)]}
 return {'id':f'{cid}-t{i}','title':path_name,'children':[make_node(n,sub,cid,f'{i}-{j}') for j,(n,sub) in enumerate(ch,1)]}
output={'version':'1.0','description':'可编辑的课程知识点建议目录。学习状态在浏览器本地单独保存；不是统一课程教学大纲。','courses':{}}
missing=[]
for m in base['majors']:
 for c in m['courses']:
  name=c['name']; cid=c['id']; chapters=calc if name=='高等数学' else syllabus.get(name)
  if not chapters: missing.append(name);continue
  output['courses'][cid]=[make_node(n,sub,cid,i) for i,(n,sub) in enumerate(chapters,1)]
assert not missing,missing
assert len(output['courses'])==65
(R/'data/course_topics.json').write_text(json.dumps(output,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def leaves(n): return 1 if not n['children'] else sum(leaves(x) for x in n['children'])
print('courses:',len(output['courses']),'knowledge leaves:',sum(leaves(n) for arr in output['courses'].values() for n in arr))
